package com.xoclassic.app;
import android.app.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Local appearance editor. Picker changes are drafts until the theme is saved. */
final class ThemeSettings {
 String section="Themes"; LinearLayout themesPage,colorsPage,schedulePage; Spinner themePicker; final Map<String,Button> subTabs=new LinkedHashMap<>(); final Map<String,View> underlines=new LinkedHashMap<>();
 final Activity activity; final AppColors.Store store; final LinearLayout target; final Runnable apply;
 ThemeSettings(Activity a,AppColors.Store s,LinearLayout t,Runnable changed){activity=a;store=s;target=t;apply=changed;render();}
 int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 TextView label(String s){TextView t=new TextView(activity);t.setText(s);t.setTextSize(16);t.setPadding(0,dp(8),0,dp(6));AppColors.text(t,0xffe1dfdc);return t;}
 Button button(String s,Runnable r){Button b=new Button(activity);b.setText(s);b.setAllCaps(false);AppColors.text(b,0xff9cbce3);GradientDrawable d=new GradientDrawable();AppColors.fill(d,0xff000002);d.setCornerRadius(dp(10));b.setBackground(d);b.setOnClickListener(v->r.run());LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,dp(48));space.setMargins(0,dp(3),0,dp(3));b.setLayoutParams(space);return b;}
 EditText entry(String hint){EditText e=new EditText(activity);e.setSingleLine(true);e.setHint(hint);AppColors.text(e,0xffe1dfdc);AppColors.hint(e,0xffa8adb5);return e;}
 Spinner choices(String chosen){Spinner s=new Spinner(activity);List<String> names=new ArrayList<>(store.themes().keySet());ArrayAdapter<String> a=new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,names){@Override public View getView(int p,View v,ViewGroup g){View out=super.getView(p,v,g);AppColors.text((TextView)out,0xffe1dfdc);return out;}@Override public View getDropDownView(int p,View v,ViewGroup g){View out=super.getDropDownView(p,v,g);AppColors.text((TextView)out,0xffe1dfdc);AppColors.background(out,0xff34383f);return out;}};s.setAdapter(a);s.setSelection(Math.max(0,names.indexOf(chosen)));return s;}
 String choice(Spinner s){return String.valueOf(s.getSelectedItem());}
 void message(String s){Toast.makeText(activity,s,Toast.LENGTH_LONG).show();}
 LinearLayout page(String tag){LinearLayout p=new LinearLayout(activity);p.setOrientation(1);p.setTag(tag);target.addView(p,new LinearLayout.LayoutParams(-1,-2));return p;}
 void showSection(String name){section=name;if(name.equals("Colors")&&colorsPage.getChildCount()==0)edit(choice(themePicker));themesPage.setVisibility(name.equals("Themes")?View.VISIBLE:View.GONE);colorsPage.setVisibility(name.equals("Colors")?View.VISIBLE:View.GONE);schedulePage.setVisibility(name.equals("Schedule")?View.VISIBLE:View.GONE);for(String key:subTabs.keySet()){boolean selected=key.equals(name);Button b=subTabs.get(key);b.setSelected(selected);AppColors.text(b,selected?0xffe1dfdc:0xff9cbce3);AppColors.background(underlines.get(key),selected?0xff9cbce3:0xff494e57);}}
 void render(){target.removeAllViews();subTabs.clear();underlines.clear();target.addView(label("Theme · "+store.current()));LinearLayout tabs=new LinearLayout(activity);tabs.setTag("theme-subtabs");tabs.setBaselineAligned(false);for(String name:new String[]{"Themes","Colors","Schedule"}){LinearLayout cell=new LinearLayout(activity);cell.setOrientation(1);Button b=button(name,()->showSection(name));b.setTag("theme-tab:"+name);AppColors.background(b,Color.TRANSPARENT);cell.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));View line=new View(activity);cell.addView(line,new LinearLayout.LayoutParams(-1,dp(2)));tabs.addView(cell,new LinearLayout.LayoutParams(0,-2,1));subTabs.put(name,b);underlines.put(name,line);}target.addView(tabs);themesPage=page("theme-page:Themes");colorsPage=page("theme-page:Colors");schedulePage=page("theme-page:Schedule");
 themesPage.addView(label("Presets and custom themes"));Spinner pick=choices(store.current());themePicker=pick;pick.setTag("theme-choice");themesPage.addView(pick);themesPage.addView(button("Apply selected theme",()->{store.prefs.edit().putString("active",choice(pick)).putBoolean("scheduled",false).apply();apply.run();render();}));themesPage.addView(button("Customize selected theme",()->edit(choice(pick))));Button delete=button("Delete custom theme",()->{String n=choice(pick);new ThemeDialogs(activity).setTitle("Delete "+n+"?").setMessage("Selections using this theme will return to Default (Light for daytime).").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{store.remove(n);apply.run();render();}).show();});delete.setTag("theme-delete-custom");themesPage.addView(delete);Runnable deleteState=()->{boolean custom=!Arrays.asList("Default","Light","Midnight","Sepia","Ocean").contains(choice(pick));delete.setEnabled(custom);delete.setAlpha(custom?1:.35f);};pick.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){deleteState.run();}public void onItemSelected(AdapterView<?> p,View v,int position,long id){deleteState.run();}});deleteState.run();themesPage.addView(label("Default restores the original appearance. Use Colors to customize a theme, or Schedule for automatic day/night switching."));
 schedulePage.addView(label("Automatic day / night"));Switch enabled=new Switch(activity);enabled.setTag("theme-schedule");enabled.setText("Change theme by time of day");AppColors.text(enabled,0xffe1dfdc);enabled.setChecked(store.prefs.getBoolean("scheduled",false));schedulePage.addView(enabled);schedulePage.addView(label("Uses local phone time. Off by default. Applying a theme manually switches the schedule off."));schedulePage.addView(label("Day theme"));Spinner day=choices(store.prefs.getString("day","Light"));schedulePage.addView(day);schedulePage.addView(label("Night theme"));Spinner night=choices(store.prefs.getString("night","Default"));schedulePage.addView(night);int[] times={store.prefs.getInt("dayTime",420),store.prefs.getInt("nightTime",1140)};Button dayTime=button("",()->{}),nightTime=button("",()->{});Runnable labels=()->{dayTime.setText("Day starts · "+time(times[0]));nightTime.setText("Night starts · "+time(times[1]));};labels.run();dayTime.setOnClickListener(v->timePicker(times,0,labels));nightTime.setOnClickListener(v->timePicker(times,1,labels));schedulePage.addView(dayTime);schedulePage.addView(nightTime);schedulePage.addView(button("Save schedule",()->{if(times[0]==times[1]){message("Choose different day and night start times");return;}store.prefs.edit().putBoolean("scheduled",enabled.isChecked()).putString("day",choice(day)).putString("night",choice(night)).putInt("dayTime",times[0]).putInt("nightTime",times[1]).apply();apply.run();message(enabled.isChecked()?"Schedule enabled":"Schedule saved · automatic switching off");render();}));showSection(section);}
 String time(int m){return String.format(Locale.getDefault(),"%02d:%02d",m/60,m%60);}
 void timePicker(int[] times,int index,Runnable labels){TimePickerDialog dialog=new TimePickerDialog(activity,AppColors.light()?android.R.style.Theme_Material_Light_Dialog_Alert:android.R.style.Theme_Material_Dialog_Alert,(v,h,m)->{times[index]=h*60+m;labels.run();},times[index]/60,times[index]%60,android.text.format.DateFormat.is24HourFormat(activity));dialog.show();AppColors.dialog(dialog);}
 void edit(String source){colorsPage.removeAllViews();int[] draft=store.themes().get(source).clone();colorsPage.addView(label("Customize · "+source));EditText name=entry("Custom theme name");name.setTag("theme-name");if(!Arrays.asList("Default","Light","Midnight","Sepia","Ocean").contains(source))name.setText(source);colorsPage.addView(name);colorsPage.addView(label("Tap a color for a picker or enter a hex value. Save and apply when finished. Switching subtabs keeps these unsaved edits."));String[] groups={"General","Controls","Threads","Search highlights"};int[][] roles={{0,1,2,3,5},{4,15,16,9},{6,7,8,10,14,17},{11,12,13}};for(int g=0;g<groups.length;g++){TextView title=label(groups[g]);title.setTypeface(Typeface.SERIF,Typeface.BOLD);title.setTag("theme-color-group:"+groups[g]);colorsPage.addView(title);for(int index:roles[g]){Button b=button("",()->{});b.setTag("theme-color:"+index);Runnable update=()->{b.setText(AppColors.LABELS[index]+" · "+AppColors.hex(draft[index]));b.setCompoundDrawablesWithIntrinsicBounds(swatch(draft[index]),null,null,null);b.setCompoundDrawablePadding(dp(12));};update.run();b.setOnClickListener(v->picker(draft,index,update));colorsPage.addView(b,new LinearLayout.LayoutParams(-1,dp(54)));}}colorsPage.addView(button("Save and apply",()->{String n=name.getText().toString().trim();try{store.save(n,draft);store.prefs.edit().putString("active",n).putBoolean("scheduled",false).apply();apply.run();section="Themes";render();message("Theme saved");}catch(IllegalArgumentException e){name.setError(e.getMessage());}}));colorsPage.addView(button("Cancel",()->{colorsPage.removeAllViews();showSection("Themes");}));colorsPage.addView(label("Photos, videos, documents and external websites keep their own colors."));showSection("Colors");}
 GradientDrawable swatch(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setSize(dp(24),dp(24));d.setCornerRadius(dp(4));d.setStroke(dp(1),AppColors.color(0xffa8adb5));return d;}
 void picker(int[] draft,int index,Runnable saved){LinearLayout panel=new LinearLayout(activity);panel.setOrientation(1);panel.setPadding(dp(20),dp(8),dp(20),dp(8));EditText hex=entry("#RRGGBB");hex.setTag("theme-color-hex");hex.setText(AppColors.hex(draft[index]));float[] hsv=new float[3];Color.colorToHSV(draft[index],hsv);SV view=new SV(activity,hsv);panel.addView(view,new LinearLayout.LayoutParams(-1,dp(180)));TextView hue=label("Hue");panel.addView(hue);SeekBar slider=new SeekBar(activity);slider.setMax(359);slider.setProgress((int)hsv[0]);panel.addView(slider);panel.addView(hex);boolean[] syncing={false};view.changed=()->{syncing[0]=true;hex.setText(AppColors.hex(Color.HSVToColor(hsv)));syncing[0]=false;};slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int n,boolean user){if(user){hsv[0]=n;view.invalidate();view.changed.run();}}});hex.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int n){}public void onTextChanged(CharSequence s,int a,int before,int count){if(syncing[0])return;try{Color.colorToHSV(AppColors.parse(s.toString()),hsv);slider.setProgress((int)hsv[0]);view.invalidate();}catch(IllegalArgumentException ignored){}}public void afterTextChanged(Editable e){}});AlertDialog dialog=new ThemeDialogs(activity).setTitle(AppColors.LABELS[index]).setView(panel).setNegativeButton("Cancel",null).setPositiveButton("Use color",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{draft[index]=AppColors.parse(hex.getText().toString());saved.run();dialog.dismiss();}catch(IllegalArgumentException e){hex.setError(e.getMessage());}}));dialog.show();}
 static final class SV extends View {final float[] hsv;final Paint paint=new Paint(3);Runnable changed=()->{};SV(Activity c,float[] h){super(c);hsv=h;setContentDescription("Color saturation and brightness picker");setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){int hue=Color.HSVToColor(new float[]{hsv[0],1,1});paint.setShader(new LinearGradient(0,0,getWidth(),0,Color.WHITE,hue,Shader.TileMode.CLAMP));c.drawRect(0,0,getWidth(),getHeight(),paint);paint.setShader(new LinearGradient(0,0,0,getHeight(),Color.TRANSPARENT,Color.BLACK,Shader.TileMode.CLAMP));c.drawRect(0,0,getWidth(),getHeight(),paint);paint.setShader(null);paint.setColor(Color.WHITE);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(4);c.drawCircle(hsv[1]*getWidth(),(1-hsv[2])*getHeight(),10,paint);paint.setStyle(Paint.Style.FILL);}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN||e.getActionMasked()==MotionEvent.ACTION_MOVE){getParent().requestDisallowInterceptTouchEvent(true);hsv[1]=Math.max(0,Math.min(1,e.getX()/Math.max(1,getWidth())));hsv[2]=1-Math.max(0,Math.min(1,e.getY()/Math.max(1,getHeight())));invalidate();changed.run();return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){performClick();return true;}return true;}public boolean performClick(){super.performClick();return true;}}
}
